/// <summary>
/// The controller class for the batch job
/// </summary>
class METPostPickListController extends SysOperationServiceController
{
    /// <summary>
    /// The new method of the class
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METPostPickListService));
        this.parmMethodName(methodStr(METPostPickListService, processOperation));
    }

    /// <summary>
    /// The caption method of the batch job dialog.
    /// </summary>
    /// <returns>String value to be used on dialog</returns>
    public ClassDescription caption()
    {
        return "@MET:METAutoPostPickList";
    }

    /// <summary>
    /// The main method of the batch job.
    /// </summary>
    /// <param name = "_args">The arguments passed by the caller object.</param>
    public static void main(Args _args)
    {
        SysOperationController controller = new METPostPickListController();
        controller.startOperation();
    }
}
